import{_ as i,C as r,o as n,c as l,a2 as a,E as s}from"./chunks/framework.CDpkVv68.js";const f=JSON.parse('{"title":"Magery Overview","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/magic/overview.md","filePath":"en/guide/magic/overview.md"}'),o={name:"en/guide/magic/overview.md"};function d(c,e,h,p,m,u){const t=r("WikiVisual");return n(),l("div",null,[e[0]||(e[0]=a('<h1 id="magery-overview" tabindex="-1">Magery Overview <a class="header-anchor" href="#magery-overview" aria-label="Permalink to &quot;Magery Overview&quot;">​</a></h1><p><strong>Status:</strong> Proposed · Availability not established.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><ul><li>Magery supports execution; <a href="/Syrolands-Public/en/guide/magic/learning-spells.html">Core Patterns</a> provide learned spell knowledge.</li><li>Practice and preparation shape which spells you can use readily.</li><li>Discovery continues beyond <a href="/Syrolands-Public/en/guide/characters/skills.html">skill</a> <a href="/Syrolands-Public/en/guide/glossary.html#mastery">mastery</a>.</li></ul><p><span id="at-a-glance"></span><span id="progression-and-trade-offs"></span></p>',5)),s(t,{"asset-id":"hero-magic"}),e[1]||(e[1]=a('<h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Element</th><th>Player meaning</th></tr></thead><tbody><tr><td>Core Pattern</td><td>A learned spell identity, with compatible variants to discover.</td></tr><tr><td>Magery</td><td>Your ability to execute a spell, not automatic knowledge of it.</td></tr><tr><td><a href="/Syrolands-Public/en/guide/characters/familiarity.html">Familiarity</a></td><td>Practice with a particular pattern.</td></tr><tr><td><a href="/Syrolands-Public/en/guide/magic/memory-and-familiarity.html">Active Memory</a></td><td>Prepared access to normal casting, never instant success.</td></tr></tbody></table><h2 id="compared-with-classic-uo" tabindex="-1">Compared with classic UO <a class="header-anchor" href="#compared-with-classic-uo" aria-label="Permalink to &quot;Compared with classic UO&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Classic UO</th><th>Syrolands direction</th></tr></thead><tbody><tr><td>Magery already involves spellbooks, skill, mana and reagents.</td><td>Keep meaningful casting resources while separating learned patterns, practice and preparation.</td></tr><tr><td>Spells in a book can be selected for casting, subject to casting requirements.</td><td>Active Memory determines ready access; known unprepared patterns may need reference time.</td></tr><tr><td>Magery has a defined spell catalogue.</td><td>Discover Core Patterns and compatible learned modifiers through the world.</td></tr></tbody></table><p>UO rules vary by era and shard. <a href="https://uo.com/wiki/ultima-online-wiki/skills/magery/" target="_blank" rel="noreferrer">Official UO: Magery and Meditation</a>.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><p>Two equally skilled mages may know different patterns. A well-prepared specialist can enter an encounter with a useful spell ready, while another needs time to consult a reference.</p><h2 id="progression-trade-offs" tabindex="-1">Progression / trade-offs <a class="header-anchor" href="#progression-trade-offs" aria-label="Permalink to &quot;Progression / trade-offs&quot;">​</a></h2><p>Wider Mastery means specialization in a discipline or affinity; it is distinct from per-pattern Familiarity. Spell eligibility, successful execution and resistance to interruption remain different questions.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><p><a href="/Syrolands-Public/en/guide/magic/learning-spells.html">Learning spells</a> · <a href="/Syrolands-Public/en/guide/magic/memory-and-familiarity.html">Memory and Familiarity</a> · <a href="/Syrolands-Public/en/guide/magic/variants-and-glyphs.html">Spell variants</a> · <a href="/Syrolands-Public/en/guide/magic/meditation-and-concentration.html">Meditation</a></p><h2 id="full-design-specification" tabindex="-1">Full design specification <a class="header-anchor" href="#full-design-specification" aria-label="Permalink to &quot;Full design specification&quot;">​</a></h2><p>Read the <a href="/Syrolands-Public/en/game-design/magic.html">Magery Overview</a> design specification.</p>',13))])}const y=i(o,[["render",d]]);export{f as __pageData,y as default};
